import java.io.*;
import java.util.*;

public class CODEFORCES {
    private InputStream is;
    private PrintWriter out;

    void solve() {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int l = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());

        StringBuilder fin = new StringBuilder();
        for (int i = 0; i < a; i++)
            fin.append((char) ('a' + i));
        for (int i = 0; i < b; i++)
            fin.append((char) ('a' + a - 1));
        int x = l % (a + b);
        if (x == 0)
            x = a + b;
        fin = new StringBuilder(fin.substring(x - 1));
        HashSet<Character> set = new HashSet<>();
        for (int i = fin.length() - 1; i >= fin.length() - a && i >= 0; i--)
            set.add(fin.charAt(i));
        int op = a;
        for (int i = 0; i < 26 && op > 0; i++) {
            char c = (char) ('a' + i);
            if (set.contains(c))
                continue;
            fin.append(c);
            op--;
        }
        char ch = fin.charAt(fin.length() - 1);
        for (int i = 0; i < b; i++)
            fin.append(ch);
        set.clear();
        for (int i = fin.length() - 1; i >= fin.length() - a && i >= 0; i--)
            set.add(fin.charAt(i));
        op = a;
        for (int i = 0; i < 26 && op > 0; i++) {
            char c = (char) ('a' + i);
            if (set.contains(c))
                continue;
            fin.append(c);
            op--;
        }
        ch = fin.charAt(fin.length() - 1);
        for (int i = 0; i < b; i++)
            fin.append(ch);
        set.clear();
        for (int i = 0; i <= r - l && i < fin.length(); i++)
            set.add(fin.charAt(i));
        out.println(set.size());
    }

    void soln() {
        is = System.in;
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        tr(System.currentTimeMillis() - s + "ms");
    }

    public static void main(String[] args) throws Exception {
        new CODEFORCES().soln();
    }
}
